// Generated files: brand.html, sitemap.xml, robots.txt and the identity SVGs. It also fills the Download links
// and the structured data in the hand-authored pages (index.html, acknowledgements.html, 404.html) from content.mjs.
import { readFile, writeFile } from 'node:fs/promises';
import { brand as b, DOWNLOAD_URL } from './content.mjs';
import { mark, buildIdentity } from './identity.mjs';
const e = value => String(value).replaceAll('BetterTile',b.name).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const iconPaths = { external:'M7 17 17 7M7 7h10v10', down:'M12 4v16m-6-6 6 6 6-6' };
const icon = (name,cls='') => `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]}"/></svg>`;
const link = (url, text, cls='') => `<a href="${url}"${cls?` class="${cls}"`:''}>${text.replaceAll('↗',icon('external'))}</a>`;
const download = (small=false) => link(b.links.download,small?'Download':`Download for Mac ${icon('down')}`,`button primary${small?' compact':''}`);
const logo = () => `<img src="${b.assets.icon}" width="40" height="40" alt=""><span>${e(b.name)}</span>`;
const absolute = path => `${b.site}${path}`;
const image = absolute('assets/identity/social-preview.png');

// Brand kit page. Not indexed.
const brandHead = `<!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><script>document.documentElement.classList.add('js')</script><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark"><meta name="theme-color" content="#07090d"><title>${e(b.name)} — Brand studio</title><meta name="description" content="${e(b.description)}"><meta property="og:type" content="website"><meta property="og:site_name" content="${e(b.name)}"><meta property="og:url" content="${absolute('brand.html')}"><meta property="og:title" content="${e(b.name)} — ${e(b.tagline)}"><meta property="og:description" content="${e(b.description)}"><meta property="og:image" content="${image}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="${e(b.name)}: ${e(b.tagline)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${e(b.name)} — ${e(b.tagline)}"><meta name="twitter:description" content="${e(b.description)}"><meta name="twitter:image" content="${image}"><meta name="twitter:image:alt" content="${e(b.name)}: ${e(b.tagline)}"><meta name="robots" content="noindex"><link rel="icon" href="favicon.ico" sizes="48x48"><link rel="icon" type="image/png" href="assets/identity/app-icon-native-dark-32.png"><link rel="apple-touch-icon" href="${b.assets.iconLarge}"><link rel="stylesheet" href="brand-base.css"><link rel="stylesheet" href="brand.css"></head>`;
const tile=(name,number,cls,concept,headline,body,palette)=>`<article class="style-tile ${cls}"><div class="tile-label"><span>0${number} / ${name}</span><span>${number===1?'Earlier exploration':'Exploration'}</span></div><div class="tile-logo">${mark(concept)}<span>${e(b.name)}</span></div><div class="tile-hero"><h3>${headline}</h3><div class="tile-panes"><i></i><b></b><i></i></div></div><p>${body}</p><div class="tile-palette">${palette.map(([color,label])=>`<span style="--swatch:${color}"><i></i>${label}</span>`).join('')}</div><p class="tile-type">${number===1?'Inter · Precise / spacious / connected':number===2?'Instrument Serif + Inter · Editorial / airy / thoughtful':'System sans + mono labels · Compact / focused / direct'}</p></article>`;

const brandPage=`${brandHead}<body class="brand-page"><a class="skip-link" href="#main">Skip to content</a><header class="site-header wrap"><a class="wordmark" href="./">${logo()}</a><a class="button secondary compact" href="./">View website ↗</a></header><main id="main" class="wrap"><section class="brand-intro section"><p class="eyebrow">Brand assets / ${e(b.checked)}</p><h1>A shared edge.<br><span>A clearer identity.</span></h1><p class="body-copy">The ${e(b.name)} identity, built around the moment two windows move together. These are the assets the website uses today. They may change as the brand develops.</p></section>
<section class="brand-section icon-colorways" id="icon-colorways"><h2>One icon. Two colorways.</h2><p class="body-copy">Current Ice Blue and Dark icons, exported from the native Icon Composer documents.</p><div class="colorway-pair">${[['light','Ice Blue','Ice-blue body, cobalt panes, mint and teal.'],['dark','Dark','Dark body, cobalt panes, mint and teal.']].map(([id,label,description])=>`<article><img src="assets/identity/app-icon-native-${id}-512.png" width="320" height="320" alt="${label} app icon"><h3>${label}</h3><p>${description}</p><a class="text-link" href="assets/identity/app-icon-native-${id}-1024.png" download>Download master PNG ↗</a><a class="text-link" href="assets/identity/app-icon-native-${id}-1024.png" download>1024 px PNG ↗</a><div class="icon-size-strip">${[16,24,32,64,128].map(size=>`<figure><img src="assets/identity/app-icon-native-${id}-${size<=32?32:size}.png" width="${size}" height="${size}" alt=""><figcaption>${size} px</figcaption></figure>`).join('')}</div></article>`).join('')}</div><p class="fine">These transparent PNGs come from the current native icon exports. Their editable source is in Resources/AppIconIce.icon and Resources/AppIconDark.icon. Earlier vector explorations remain below for reference.</p></section><section class="brand-section" aria-labelledby="directions"><p class="eyebrow">01 / Three directions</p><h2 id="directions">Different expressions.<br><span>One useful idea.</span></h2><div class="style-tiles">${tile('Shared Edge',1,'direction-edge','rail','Make room<br><span>for your work.</span>','An earlier direction with pitch black fading into cobalt, open frames, and one active teal boundary. The interface explains the identity; the identity explains the interface.',[['#000000','Black'],['#315cf4','Cobalt'],['#63dec0','Teal']])}${tile('Open Space',2,'direction-open','frame','A place<br><em>to think.</em>','A cool, bright editorial direction with an adaptable frame. Spacious and approachable, with less connection to the current dark app icon.',[['#f1f4f7','Paper'],['#1b2434','Ink'],['#405be8','Ultramarine']])}${tile('Quiet Instrument',3,'direction-instrument','type','WINDOWS.<br>IN CONCERT.','A compact typographic mark and monochrome utility language. Precise, but less welcoming and less direct about linked resizing.',[['#0b0d10','Black'],['#e9eef5','Silver'],['#a7b3c2','Slate']])}</div></section>
<section class="brand-section"><div class="section-heading"><div><p class="eyebrow">02 / Symbol explorations</p><h2>Draw the relationship.</h2></div><p>Three original constructions. Earlier vector studies. The website uses the glass icon shown above.</p></div><div class="logo-concepts"><article>${mark('rail')}<h3>A / Shared rail</h3><p>Two open brackets and a taller common edge. Recognizable in one color. The gap stays useful at small sizes.</p></article><article>${mark('frame')}<h3>B / Adaptable frame</h3><p>An offset frame makes room for another shape. More architectural, but less immediately about linked movement.</p></article><article>${mark('type')}<h3>C / Joined initials</h3><p>A drawn B and T share a baseline. Name-dependent, with less visual separation at menu-bar sizes.</p></article></div></section>
<section class="brand-section"><p class="eyebrow">03 / Developed identity</p><h2>Separate windows.<br><span>Common ground.</span></h2><div class="identity-lockup">${mark()}<span>${e(b.name)}</span></div><div class="identity-examples"><div class="identity-light"><img src="assets/identity/symbol-mono.svg" width="110" height="110" alt="Monochrome Shared Edge symbol"><span>Monochrome</span></div><div><img src="assets/identity/symbol-white.svg" width="110" height="110" alt="White Shared Edge symbol"><span>Reversed</span></div><div class="icon-pair"><img src="assets/identity/app-icon-native-dark-128.png" width="108" height="108" alt="Current BetterTile app icon"><img src="${b.assets.icon}" width="128" height="128" alt="Current native Dark app icon"><span>Classic → native Dark icon</span></div></div><div class="small-size-test">${[16,24,32,64,128].map(size=>`<figure><img src="assets/identity/symbol-${size}.svg" width="${size}" height="${size}" alt="Shared Edge at ${size} pixels"><figcaption>${size} px</figcaption></figure>`).join('')}</div><p class="fine">The 16 px version uses a separate pixel-aligned drawing. Core silhouette tested without blur, gradients, or animation. Menu bar uses one opaque color.</p><div class="context-grid"><div class="menu-context"><span>Finder &nbsp; File &nbsp; Edit</span><img src="assets/identity/menu-bar.svg" width="16" height="16" alt="Monochrome menu bar icon"><span>9:41</span></div><div class="download-context"><img src="${b.assets.icon}" width="64" height="64" alt="Native Dark app icon"><div><b>${e(b.name)}</b><p>A little more room.</p></div>${download(true)}</div></div><img class="social-example" src="assets/identity/social-preview.svg" width="1200" height="630" alt="Social preview showing BetterTile's headline, symbol, and a shared window boundary" loading="lazy"><div class="asset-links">${['symbol.svg','symbol-mono.svg','symbol-reversed.svg','wordmark.svg','lockup.svg','lockup-reversed.svg','favicon.svg','menu-bar.svg','social-preview.svg'].map(file=>link('assets/identity/'+file,file)).join('')}</div><p class="fine">SVGs are editable. Wordmark files use Inter; the font and OFL license are bundled. The complete set also includes white and small-size symbols.</p></section>
<section class="brand-section"><p class="eyebrow">04 / Brand foundation</p><div class="foundation-grid"><article><h3>Promise</h3><p>Keep your windows working together, so your attention can stay on the work.</p></article><article><h3>Personality</h3><p>Precise. Calm. Approachable.</p></article><article><h3>Voice</h3><p>Say what happens. Explain the next move. Prefer concrete verbs and honest beta details to performance claims.</p></article><article><h3>Central idea</h3><p>A shared edge. Repeated in the mark, the active boundary, paired compositions, and coordinated motion.</p></article></div></section>
</main><footer class="site-footer wrap"><a class="wordmark" href="./">${logo()}</a><p>${e(b.name)} brand assets · Used on this website.</p></footer></body></html>`;


// Hand-authored pages. Every <a data-download> gets DOWNLOAD_URL, and the home page's JSON-LD is rebuilt from
// content.mjs, so a new download link needs a change in one place only.
const ld = data => `<script type="application/ld+json">${JSON.stringify(data).replaceAll('<','\\u003c')}</script>`;
// Structured data for search engines. downloadUrl is the stable download link. No version is listed, so the data cannot go stale.
const softwareLd = () => ld({'@context':'https://schema.org','@type':'SoftwareApplication',name:b.name,description:b.description,url:b.site,image,operatingSystem:'macOS 26 or later',applicationCategory:'UtilitiesApplication',downloadUrl:DOWNLOAD_URL,releaseNotes:b.links.latest,license:'https://www.gnu.org/licenses/gpl-3.0.html',offers:{'@type':'Offer',price:'0',priceCurrency:'USD'}});
export const fill = html => html
  .replace(/<a\b[^>]*\bdata-download\b[^>]*>/g, tag => tag.replace(/\bhref="[^"]*"/, `href="${DOWNLOAD_URL}"`))
  .replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>/, softwareLd);
for (const file of ['index.html','acknowledgements.html','404.html']) {
  const html = await readFile(file,'utf8'), filled = fill(html);
  if (filled !== html) await writeFile(file, filled);
}

const sitemap = `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${['','acknowledgements.html'].map(path=>`  <url><loc>${absolute(path)}</loc></url>`).join('\n')}\n</urlset>\n`;
const robots = `User-agent: *\nAllow: /\n\nSitemap: ${absolute('sitemap.xml')}\n`;

await buildIdentity();
await writeFile('brand.html',brandPage);
await writeFile('sitemap.xml',sitemap);
await writeFile('robots.txt',robots);
